## ✅ Recommended Secure Secrets Management

### Option A: AWS Secrets Manager (Production Recommended)

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsClient = new SecretsManagerClient({ region: process.env.AWS_REGION });

let cachedSecrets = null;
let lastFetch = 0;
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function loadSecrets(secretName) {
  // Return cached secrets if fresh
  if (cachedSecrets && (Date.now() - lastFetch) < CACHE_TTL) {
    return cachedSecrets;
  }

  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await secretsClient.send(command);

    cachedSecrets = JSON.parse(response.SecretString);
    lastFetch = Date.now();

    return cachedSecrets;
  } catch (error) {
    console.error('Failed to load secrets:', error);
    throw new Error('Secret loading failed');
  }
}

// Validate required secrets on startup
function validateSecrets(secrets) {
  const required = ['DATABASE_URL', 'JWT_SECRET', 'STRIPE_SECRET_KEY'];
  const missing = required.filter(key => !secrets[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }
}

module.exports = { loadSecrets, validateSecrets };
```

