### 4. **Secret Rotation Strategy**

```javascript
// utils/secretRotator.js

class SecretRotator {
  constructor(secretsManager) {
    this.secretsManager = secretsManager;
    this.cache = new Map();
    this.rotationInterval = 24 * 60 * 60 * 1000; // 24 hours
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.rotationInterval) {
      return cached.value;
    }

    // Fetch fresh from secrets manager
    const fresh = await this.secretsManager.getSecretValue(secretName);

    // Update cache
    this.cache.set(secretName, {
      value: fresh,
      timestamp: Date.now()
    });

    return fresh;
  }

  // Gracefully handle rotation
  async getSecretWithFallback(secretName, fallbackSecretName) {
    try {
      return await this.getSecret(secretName);
    } catch (error) {
      console.warn(`Primary secret ${secretName} failed, trying fallback`);
      return await this.getSecret(fallbackSecretName);
    }
  }
}

module.exports = SecretRotator;
```

