**Implementation:**

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsClient = new SecretsManagerClient({ 
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache for secrets to avoid repeated API calls
const secretCache = new Map();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getSecret(secretName) {
  // Check cache first
  const cached = secretCache.get(secretName);
  if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
    return cached.value;
  }

  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await secretsClient.send(command);

    const secretValue = response.SecretString;

    // Parse if JSON
    let parsedValue;
    try {
      parsedValue = JSON.parse(secretValue);
    } catch {
      parsedValue = secretValue;
    }

    // Update cache
    secretCache.set(secretName, {
      value: parsedValue,
      timestamp: Date.now()
    });

    return parsedValue;
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error);
    throw error;
  }
}

// Pre-load critical secrets at startup
async function loadSecrets() {
  const [
    databaseConfig,
    stripeConfig,
    apiKeys
  ] = await Promise.all([
    getSecret('prod/myapp/database'),
    getSecret('prod/myapp/stripe'),
    getSecret('prod/myapp/api-keys')
  ]);

  return {
    databaseUrl: databaseConfig.connection_string,
    stripeSecretKey: stripeConfig.secret_key,
    anthropicApiKey: apiKeys.anthropic
  };
}

module.exports = { getSecret, loadSecrets };
```

