// scripts/rotate-and-verify.js
const { 
  SecretsManagerClient, 
  RotateSecretCommand,
  DescribeSecretCommand 
} = require('@aws-sdk/client-secrets-manager');

async function rotateAndVerify(secretId) {
  const client = new SecretsManagerClient({ region: 'us-east-1' });

  console.log(`Initiating rotation for: ${secretId}`);

  // Trigger rotation
  await client.send(new RotateSecretCommand({
    SecretId: secretId,
    ClientRequestToken: `manual-${Date.now()}`
  }));

  // Poll for completion (version stage changes)
  let attempts = 0;
  const maxAttempts = 30;

  while (attempts < maxAttempts) {
    const desc = await client.send(
      new DescribeSecretCommand({ SecretId: secretId })
    );

    // Check rotation completed
    const versions = desc.VersionIdsToStages || {};
    const hasCurrent = Object.values(versions)
      .some(stages => stages.includes('AWSCURRENT'));
    const hasPending = Object.values(versions)
      .some(stages => stages.includes('AWSPENDING'));

    if (hasCurrent && !hasPending) {
      console.log(`✅ Rotation complete for ${secretId}`);
      console.log(`   New version: ${desc.LastRotatedDate}`);
      return { secretId, status: 'complete', rotatedAt: desc.LastRotatedDate };
    }

    console.log(`   Waiting... attempt ${attempts + 1}/${maxAttempts}`);
    await new Promise(r => setTimeout(r, 10000));
    attempts++;
  }

  throw new Error(`Rotation timeout for ${secretId}`);
}

// Rotate all application secrets
