app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization
app.use(mongoSanitize()); // NoSQL injection prevention
app.use(xss()); // XSS prevention
app.use(hpp()); // HTTP Parameter Pollution prevention

