// config/validateEnv.js
const requiredEnvVars = {
  // Format: [variable, sensitive?]
  NODE_ENV: false,
  PORT: false,
  DATABASE_URL: true,
  JWT_SECRET: true,
  AWS_REGION: false,
  // Never load these directly - use secrets manager instead:
  // AWS_ACCESS_KEY_ID: true,  // ❌ Wrong approach
};

function validateEnvironment() {
  const missing = [];
  const exposed = [];

  for (const [varName, isSensitive] of Object.entries(requiredEnvVars)) {
    if (!process.env[varName]) {
      missing.push(varName);
    }

    // Warn if sensitive values are in environment
    if (isSensitive && process.env[varName]) {
      exposed.push(varName);
    }
  }

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  if (exposed.length > 0) {
    console.warn('⚠️  WARNING: Sensitive values detected in environment variables:', exposed);
    console.warn('   Consider using a secrets manager instead.');
  }

  // Validate NODE_ENV
  const validEnvs = ['development', 'staging', 'production'];
  if (!validEnvs.includes(process.env.NODE_ENV)) {
    throw new Error(`Invalid NODE_ENV: ${process.env.NODE_ENV}. Must be one of: ${validEnvs.join(', ')}`);
  }
}

module.exports = { validateEnvironment };
