    this.currentSecrets = {};
    this.rotationInterval = null;
  }

  async initialize() {
    this.currentSecrets = await this.loadSecrets();

    // Set up rotation check (every 5 minutes)
    this.rotationInterval = setInterval(async () => {
      await this.checkForRotation();
    }, 300000);
  }

  async loadSecrets() {
    return {
      database: await this.secretsManager.getSecret('database'),
      stripe: await this.secretsManager.getSecret('stripe'),
      anthropic: await this.secretsManager.getSecret('anthropic')
    };
  }

  async checkForRotation() {
    try {
      const newSecrets = await this.loadSecrets();

      // Simple hash comparison to detect changes
      if (JSON.stringify(newSecrets) !== JSON.stringify(this.currentSecrets)) {
        console.log('Secret rotation detected, updating...');
        this.currentSecrets = newSecrets;

        // Emit event for components to reconnect
        this.emit('secrets:rotated', newSecrets);
      }
    } catch (err) {
      console.error('Secret rotation check failed:', err);
    }
  }

  get(scope) {
    return this.currentSecrets[scope];
  }

  stop() {
    if (this.rotationInterval) {
      clearInterval(this.rotationInterval);
    }
  }
}

// Graceful handling of rotated database credentials
rotatableSecrets.on('secrets:rotated', async (secrets) => {
  // Create new connection pool with new credentials
  const newPool = new Pool(secrets.database);

  // Gracefully drain old pool
  await app.locals.db.end();

  // Swap pools
  app.locals.db = newPool;
});
