    // Warn about sensitive values
    const sensitivePatterns = [
      /password/i,
      /secret/i,
      /key/i,
      /token/i,
      /apikey/i,
      /auth/i
    ];

    for (const [key, value] of Object.entries(process.env)) {
      if (sensitivePatterns.some(p => p.test(key)) && value && value.length > 5) {
        console.warn(`⚠️  Sensitive value detected in env var: ${key}`);
        console.warn(`   Consider using a secrets manager in production`);
