                    │  IAM Auth/IAM   │
                    │  Role/Identity  │
                    └─────────────────┘
```

### Implementation Example

```javascript
// config/secrets.js - Centralized secrets management
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.CACHE_TTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.CACHE_TTL) {
      return cached.value;
    }

    // Fetch from AWS
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString();
      }

      // Cache with timestamp
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error('Secret retrieval failed');
    }
  }

  clearCache() {
    this.cache.clear();
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

// Specific secret getters
module.exports = {
  async getDatabaseConfig() {
    return secretsManager.getSecret('prod/myapp/database');
  },

  async getStripeConfig() {
    return secretsManager.getSecret('prod/myapp/stripe');
  },

  async getJWTSecret() {
    return secretsManager.getSecret('prod/myapp/jwt');
  }
};
```

