// utils/secretAudit.js
const fs = require('fs');
const path = require('path');

class SecretAuditor {
  constructor() {
    this.patterns = {
      'AWS Access Key': /AKIA[0-9A-Z]{16}/g,
      'AWS Secret Key': /["\'][A-Za-z0-9/+=]{40}["\']/g,
      'Private Key': /-----BEGIN (RSA |EC |DSA |OPENSSH )?PRIVATE KEY-----/g,
      'Stripe Live Key': /sk_live_[a-zA-Z0-9]{24,}/g,
      'API Key Generic': /['"](api[_-]?key|apikey)['"]\s*[:=]\s*['"][^'"]{16,}['"]/gi,
      'Connection String': /(mongodb|postgres|mysql|redis):\/\/[^:]+:[^@]+@/gi
    };
  }

  scanFile(filePath) {
    const content = fs.readFileSync(filePath, 'utf8');
    const findings = [];

    for (const [name, pattern] of Object.entries(this.patterns)) {
      const matches = content.match(pattern);
      if (matches) {
        findings.push({
          type: name,
          count: matches.length,
          locations: this.findLocations(content, pattern)
        });
      }
    }

    return findings;
  }

  findLocations(content, pattern) {
    const lines = content.split('\n');
    const locations = [];

    lines.forEach((line, index) => {
      if (pattern.test(line)) {
        // Mask the actual secret in logs
        const masked = line.replace(pattern, match => 
          match.slice(0, 4) + '***' + match.slice(-4)
        );
        locations.push({ line: index + 1, content: masked });
      }
      // Reset regex lastIndex for global patterns
      pattern.lastIndex = 0;
    });

    return locations;
  }

  scanDirectory(dirPath, extensions = ['.js', '.env', '.json', '.yml', '.yaml']) {
    const results = [];
    const files = fs.readdirSync(dirPath);

    for (const file of files) {
      const fullPath = path.join(dirPath, file);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory() && !file.startsWith('.') && file !== 'node_modules') {
        results.push(...this.scanDirectory(fullPath, extensions));
      } else if (extensions.some(ext => file.endsWith(ext))) {
        const findings = this.scanFile(fullPath);
        if (findings.length > 0) {
          results.push({ file: fullPath, findings });
        }
      }
    }

    return results;
  }
}

