```javascript
// scripts/rotate-secrets.js
// A proper rotation script that NEVER reads existing values

const { SecretsManagerClient, PutSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const crypto = require('crypto');

async function rotateSecret(secretName, generateNewValue) {
  // Generate new secret WITHOUT reading the old one
  const newValue = await generateNewValue();

  // Store in secrets manager
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

  await client.send(new PutSecretValueCommand({
    SecretId: secretName,
    SecretString: newValue,
    // This is proper rotation - old value remains accessible via AWSPREVIOUS
  }));

  console.log(`Rotated: ${secretName}`);
  console.log(`New value prefix: ${newValue.slice(0, 4)}***`);

  return newValue;
}

// Rotate database password
await rotateSecret('prod/db/password', async () => {
  // Generate cryptographically secure password
  return crypto.randomBytes(32).toString('base64');
});

// Rotate API key
await rotateSecret('prod/stripe/api-key', async () => {
  // Generate new key via Stripe API - never reads old one
  const response = await fetch('https://api.stripe.com/v1/keys', {
    method: 'POST',
    headers: { Authorization: `Bearer ${process.env.STRIPE_ADMIN_KEY}` }
  });
  return response.secret;
});
