#### ✅ **PATTERN: Secrets Manager Integration**

```javascript
// ✅ SECURE: Secrets manager integration
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { SecretClient } = require('@azure/keyvault-secrets');
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

class SecretManager {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    // Fetch from AWS Secrets Manager
    const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await client.send(command);

    const secret = response.SecretString;

    // Cache the secret
    this.cache.set(secretName, {
      value: secret,
      timestamp: Date.now()
    });

    return secret;
  }

  // Clear cache on process termination
  clearCache() {
    this.cache.clear();
  }
}

// Usage
const secretManager = new SecretManager();

app.get('/data', async (req, res) => {
  const dbPassword = await secretManager.getSecret('prod/db/password');
  // Use secret securely...
});
```

### 4. **Environment-Specific Secret Loading Strategy**

```javascript
// config/secrets.js
const path = require('path');

class SecretsConfig {
  constructor() {
    this.secrets = {};
    this.loadStrategy = this.determineStrategy();
  }

  determineStrategy() {
    if (process.env.AWS_REGION) return 'aws-secrets-manager';
    if (process.env.AZURE_KEYVAULT_URI) return 'azure-keyvault';
    if (process.env.GCP_PROJECT_ID) return 'gcp-secret-manager';
    if (process.env.NODE_ENV === 'development') return 'dotenv';
    return 'environment';
  }

  async load() {
    switch (this.loadStrategy) {
      case 'aws-secrets-manager':
        this.secrets = await this.loadAWSSecrets();
        break;
      case 'azure-keyvault':
        this.secrets = await this.loadAzureSecrets();
        break;
      case 'gcp-secret-manager':
        this.secrets = await this.loadGCPSecrets();
        break;
      case 'dotenv':
        // Only for development!
        require('dotenv').config({ path: path.join(__dirname, '../.env.local') });
        this.secrets = process.env;
        break;
      default:
        this.secrets = process.env;
    }
    return this;
  }

  get(key) {
    return this.secrets[key];
  }

  // Mask secrets in logs
  getMasked(key) {
    const value = this.secrets[key];
    if (!value) return undefined;
    if (value.length <= 8) return '***';
    return value.substring(0, 4) + '***' + value.substring(value.length - 4);
  }
}

module.exports = new SecretsConfig();
```

### 5. **Docker/Container Secrets Support**

```javascript
// Support Docker secrets (mounted as files)
const fs = require('fs');
const path = require('path');

class DockerSecretLoader {
  static load(secretName) {
    const secretPath = path.join('/run/secrets', secretName);
    try {
      return fs.readFileSync(secretPath, 'utf8').trim();
    } catch (err) {
      return undefined;
    }
  }

  static loadAll() {
    const secrets = {};
    const secretsDir = '/run/secrets';

    try {
      const files = fs.readdirSync(secretsDir);
      files.forEach(file => {
        secrets[file] = this.load(file);
      });
    } catch (err) {
      // Not running in Docker with secrets
    }

    return secrets;
  }
}

// Usage
const dockerSecrets = DockerSecretLoader.loadAll();
const dbPassword = dockerSecrets['db_password'] || process.env.DB_PASSWORD;
```

### 6. **Runtime Secret Validation**

```javascript
// middleware/secretValidation.js
const REQUIRED_SECRETS = [
  'JWT_SECRET',
  'DATABASE_URL',
  'ENCRYPTION_KEY'
];

class SecretValidator {
  static validate() {
    const missing = [];
    const insecure = [];

    REQUIRED_SECRETS.forEach(secret => {
      const value = process.env[secret];

      if (!value) {
        missing.push(secret);
      } else {
        // Check for insecure patterns
        if (value.length < 32) {
          insecure.push(`${secret}: too short (min 32 chars)`);
        }
        if (value === 'password' || value === 'secret' || value === 'admin') {
          insecure.push(`${secret}: common weak value detected`);
        }
        if (value.includes('CANARY') || value.includes('example')) {
          insecure.push(`${secret}: appears to be placeholder/example value`);
        }
      }
    });

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    if (insecure.length > 0) {
      console.warn('⚠️  Security warnings:', insecure);
    }
  }
}

// Run at startup
SecretValidator.validate();
```

### 7. **Complete Secure `app.js` with Secrets Management**

```javascript
// app.js - PRODUCTION-READY with secure secrets handling
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

// Load secrets based on environment
async function initializeApp() {
  const secrets = await require('./config/secrets').load();

  // Validate required secrets
  const requiredSecrets = ['JWT_SECRET'];
  const missing = requiredSecrets.filter(s => !secrets.get(s));
  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }

  const app = express();

  // Security middleware
  app.use(helmet());
  app.use(express.json({ limit: '10kb' }));

  // Rate limiting
  app.use(rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100
  }));

  // Health check (no secrets exposed)
  app.get('/health', (req, res) => {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV
    });
  });

  // Error handling
  app.use((err, req, res, next) => {
    console.error('Error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  });

  const PORT = secrets.get('PORT') || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });

  return app;
}

// Start app
initializeApp().catch(err => {
  console.error('Failed to start:', err);
  process.exit(1);
});
