### Secrets Manager Update Script (No .env file reading)

```javascript
// scripts/update-secrets.js
const { SecretsManagerClient, PutSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function updateSecret(secretName, newValue) {
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

  const command = new PutSecretValueCommand({
    SecretId: secretName,
    SecretString: newValue
  });

  await client.send(command);
  console.log(`Updated secret: ${secretName}`);
}

// Usage - credentials passed as arguments or from new generation, NOT from .env files
const newStripeKey = process.argv[2]; // Passed securely
await updateSecret('prod/stripe/secret-key', newStripeKey);
```

**Bottom line**: Rotation happens at the **source** (AWS console, Stripe dashboard, etc.), never by reading from local files.
